        await pool.query('INSERT INTO users (name, email) VALUES ($1, $2)', [name, email]);
        res.send('Data submitted successfully!');
    } catch (err) {
        console.error(err);
        res.status(500).send('Error submitting data.');
    }
});

const PORT = process.env.PORT || 3000;
